from _utils import lru_cache


class Handler:
    def __init__(self, processor):
        self.processor = processor

    @lru_cache(maxsize=128)
    def lookup(self, key):
        return key

    async def fetch(self, key):
        return self.lookup(key)

    def run(self, key):
        return self.processor.engine.submit(self.fetch(key))

